// Normalize the incoming webhook into one flat shape.
// Verified against the real production payload:
//   body.contact.{name,phone}
//   body.message.{type,text,media}
//   body.{event,direction,source,account_id,conversation_id,wa_message_id,timestamp}
// Flat variants ("FirstName", "Message Content", ...) are also accepted, in case the
// sending system is later changed to post them.
//
// NOT PRESENT in the payload and therefore always empty here:
//   ContactID, LastName, Status, Assignee, the business WhatsApp number.
// Those must be added by the system that calls this webhook, or fetched from its
// API using conversation_id. Country is derived from the phone prefix instead.

const DIAL_TO_ISO = {
  '971': 'AE', '966': 'SA', '963': 'SY', '965': 'KW', '974': 'QA', '973': 'BH',
  '968': 'OM', '962': 'JO', '961': 'LB', '964': 'IQ', '967': 'YE', '970': 'PS',
  '20': 'EG', '212': 'MA', '213': 'DZ', '216': 'TN', '218': 'LY', '249': 'SD',
  '90': 'TR', '98': 'IR', '93': 'AF', '92': 'PK', '91': 'IN', '880': 'BD',
  '94': 'LK', '977': 'NP', '1': 'US', '44': 'GB', '33': 'FR', '49': 'DE',
  '34': 'ES', '39': 'IT', '31': 'NL', '32': 'BE', '41': 'CH', '43': 'AT',
  '46': 'SE', '47': 'NO', '45': 'DK', '358': 'FI', '351': 'PT', '30': 'GR',
  '48': 'PL', '40': 'RO', '380': 'UA', '7': 'RU', '86': 'CN', '81': 'JP',
  '82': 'KR', '84': 'VN', '66': 'TH', '65': 'SG', '60': 'MY', '62': 'ID',
  '63': 'PH', '61': 'AU', '64': 'NZ', '27': 'ZA', '234': 'NG', '254': 'KE',
  '251': 'ET', '252': 'SO', '55': 'BR', '52': 'MX', '54': 'AR', '56': 'CL',
  '57': 'CO', '58': 'VE', '51': 'PE', '995': 'GE', '994': 'AZ', '996': 'KG',
  '998': 'UZ'
};

// Longest prefix first, so '971' wins over '97'/'9'.
const DIAL_CODES = Object.keys(DIAL_TO_ISO).sort((a, b) => b.length - a.length);

const countryFromPhone = (phone) => {
  const digits = String(phone || '').replace(/[^0-9]/g, '');
  if (!digits) return '';
  for (const code of DIAL_CODES) {
    if (digits.startsWith(code)) return DIAL_TO_ISO[code];
  }
  return '';
};

const out = [];

for (const item of $input.all()) {
  const b = item.json.body ?? item.json ?? {};

  const get = (path) =>
    path.split('.').reduce((o, k) => (o === null || o === undefined ? undefined : o[k]), b);

  const pick = (...paths) => {
    for (const p of paths) {
      const v = get(p);
      if (v !== undefined && v !== null && v !== '') return v;
    }
    return '';
  };

  const str = (v) => (v === undefined || v === null ? '' : String(v));

  // --- name: payload sends one combined string, so split only as a fallback ---
  const fullNameRaw = str(pick('contact.name', 'name', 'sender.name', 'FullName'));
  let firstName = str(pick('FirstName', 'first_name', 'contact.first_name'));
  let lastName = str(pick('LastName', 'last_name', 'contact.last_name'));
  if (!firstName && fullNameRaw) {
    const parts = fullNameRaw.trim().split(/\s+/);
    firstName = parts.shift() || '';
    if (!lastName) lastName = parts.join(' ');
  }
  const senderName = (fullNameRaw || firstName + ' ' + lastName).trim();

  const senderPhone = str(pick(
    'PhoneNumber', 'phone', 'phone_number', 'contact.phone', 'contact.phone_number'
  ));

  // --- timestamp: Firestore timestampValue needs RFC3339; force UTC Z ---
  const rawDate = pick('Date & Current Time', 'DateTime', 'timestamp', 'created_at', 'message.created_at');
  let messageAtUtc = '';
  if (rawDate !== '') {
    const ms = typeof rawDate === 'number' && rawDate < 1e12 ? rawDate * 1000 : rawDate;
    const d = new Date(ms);
    if (!isNaN(d.getTime())) messageAtUtc = d.toISOString();
  }

  // No contact id in the payload -- the phone is the only stable per-person key.
  const contactId = str(pick('ContactID', 'contact_id', 'contact.id', 'id')) || senderPhone;

  out.push({
    json: {
      contactId,
      conversationId: str(pick('conversation_id', 'ConversationID', 'conversation.id')),
      accountId: str(pick('account_id', 'AccountID')),
      waMessageId: str(pick('wa_message_id', 'message.id', 'MessageID')),

      firstName,
      lastName,
      senderName,
      senderPhone,
      // Guaranteed non-empty, so the app always has something to render.
      displayName: senderName || senderPhone || 'Unknown',
      country: str(pick('Country', 'country', 'contact.country_code', 'contact.country'))
        || countryFromPhone(senderPhone),

      // Absent from this payload -- kept so the shape is stable once it is added.
      conversationStatus: str(pick('Status', 'status', 'conversation.status')),
      assignee: str(pick('Assignee', 'assignee', 'assignee.name', 'conversation.assignee.name')),

      channel: str(pick('Channels', 'Channel', 'channel', 'inbox.name', 'source')),
      source: str(pick('source', 'Source')),
      event: str(pick('event', 'Event')),

      messageText: str(pick('Message Content', 'message.text', 'message.content', 'text', 'content')),
      messageType: str(pick('message.type', 'MessageType', 'Type', 'type') || 'text').toLowerCase(),
      direction: str(pick('Incoming/Outgoing', 'direction', 'message_type')).toLowerCase(),

      messageAtUtc,
      messageAtRaw: str(rawDate),

      mediaBase64: str(pick('message.media.data', 'media.data', 'MediaData', 'attachment.data')),
      mediaMimeType: str(pick('message.media.mime_type', 'media.mime_type', 'MediaMimeType')),

      body: b
    }
  });
}

return out;

// The AI Agent node only ever outputs { output: {...} } -- it structurally cannot
// carry the webhook data through. Re-join the classification with the normalized
// contact/message context here, and build the Firestore document in real JS so
// quotes, newlines, emoji and Arabic cannot corrupt the request body.

const items = $input.all();
const result = [];

const str = (v) => (v === undefined || v === null ? '' : String(v));

// Importing this workflow next to the old one makes n8n suffix node names with
// "1", so probe both spellings instead of hard-failing on a rename.
const nodeJson = (names, i) => {
  for (const name of names) {
    try {
      const all = $(name).all();
      const it = all[i] ?? all[0];
      if (it) return it.json;
    } catch (e) {
      // node absent on this canvas, or its branch did not execute this run
    }
  }
  return {};
};

// The app matches these against a fixed list, so coerce to lower_snake_case.
const snake = (v) =>
  String(v || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');

const PRIORITIES = ['urgent', 'high', 'medium', 'low'];

for (let i = 0; i < items.length; i++) {
  const agent = items[i].json.output ?? items[i].json ?? {};
  const n = nodeJson(['Normalize Payload', 'Normalize Payload1'], i);
  const branch = nodeJson([
    'Text Input', 'Text Input1',
    'Image Input', 'Image Input1',
    'Audio Input', 'Audio Input1'
  ], i);

  const nowIso = new Date().toISOString();
  const needsAttention = agent.needs_attention === true;

  let priority = snake(agent.priority);
  if (!PRIORITIES.includes(priority)) priority = needsAttention ? 'medium' : 'low';

  // --- what the app should render in the message bubble ---
  // Text: the customer's own words.
  // Image / audio: the AI description or transcription, because there are no words
  // to show. display_source tells the app which badge to put above the bubble, so
  // an analysis is never mistaken for something the customer actually wrote.
  const messageType = str(n.messageType) || 'text';
  const isMedia = messageType === 'image' || messageType === 'audio';
  const mediaAnalysis = isMedia ? str(branch.input) : '';
  const displayText = isMedia ? mediaAnalysis || str(n.messageText) : str(n.messageText);
  const displaySource = !isMedia
    ? 'customer_message'
    : messageType === 'audio' ? 'audio_transcript' : 'image_description';

  result.push({
    json: {
      fields: {
        // --- AI Agent classification ---
        needs_attention: { booleanValue: needsAttention },
        priority: { stringValue: priority },
        department: { stringValue: snake(agent.department) },
        category: { stringValue: snake(agent.category) },
        summary: { stringValue: str(agent.summary) },
        reason: { stringValue: str(agent.reason) },
        action: { stringValue: str(agent.action) },

        // --- Contact ---
        contact_id: { stringValue: str(n.contactId) },
        first_name: { stringValue: str(n.firstName) },
        last_name: { stringValue: str(n.lastName) },
        sender_name: { stringValue: str(n.senderName) },
        display_name: { stringValue: str(n.displayName) },
        sender_phone: { stringValue: str(n.senderPhone) },
        country: { stringValue: str(n.country) },

        // --- Conversation ---
        conversation_id: { stringValue: str(n.conversationId) },
        account_id: { stringValue: str(n.accountId) },
        wa_message_id: { stringValue: str(n.waMessageId) },
        channel: { stringValue: str(n.channel) },
        source: { stringValue: str(n.source) },
        // Empty until the sending system includes these in the webhook.
        conversation_status: { stringValue: str(n.conversationStatus) },
        assignee: { stringValue: str(n.assignee) },

        // --- Message ---
        // ALWAYS the customer's own words: the text body, or a media caption.
        // Empty when media is sent with no caption.
        message_content: { stringValue: str(n.messageText) },
        message_type: { stringValue: messageType },
        direction: { stringValue: str(n.direction) },
        // AI transcription (audio) or description (image). Empty for text messages.
        media_analysis: { stringValue: mediaAnalysis },
        // Ready to render: the bubble text, plus what kind of content it is.
        display_text: { stringValue: displayText },
        display_source: { stringValue: displaySource },

        // --- Timestamps (RFC3339 UTC) ---
        message_at: { timestampValue: n.messageAtUtc || nowIso },
        created_at: { timestampValue: nowIso },

        // --- Alert lifecycle. Name kept as "status" so the existing app keeps working.
        status: { stringValue: 'new' }
      }
    }
  });
}

return result;

// Builds one FCM v1 request body per registered device.
//
// Reads the Firestore CREATE RESPONSE from 'HTTP Request1' rather than the
// pre-write body, for two reasons: only alerts that actually persisted should
// notify anyone, and the response carries the generated document id, so
// alert_id is real and a future app version can deep-link to it.

const AR_PRIORITY = {
  urgent: 'عاجلة',
  high: 'عالية',
  medium: 'متوسطة',
  low: 'منخفضة',
};
const AR_DEPARTMENT = {
  sales: 'المبيعات',
  operations: 'العمليات',
  delivery: 'التوصيل',
  finance: 'المالية',
  support: 'الدعم',
  management: 'الإدارة',
};

const created = $('HTTP Request1').first().json ?? {};
const f = created.fields ?? {};

const priority = String(f.priority?.stringValue ?? '').toLowerCase();
const department = String(f.department?.stringValue ?? '').toLowerCase();
// name is "projects/.../documents/alerts/<docId>".
const alertId = String(created.name ?? '').split('/').pop() ?? '';

// Priority and department ONLY. Never the customer's message text -- a
// notification body renders on a locked screen in full view of the room, and
// these are complaints and refund demands.
const title = 'تنبيه جديد';
const body = [AR_PRIORITY[priority] || 'تنبيه', AR_DEPARTMENT[department]]
  .filter(Boolean)
  .join(' · ');

// Firestore REST returns { documents: [...] } and omits the key when empty.
const docs = $input.first().json?.documents ?? [];

return docs
  .map((d) => d.fields?.token?.stringValue)
  .filter(Boolean)
  .map((token) => ({
    json: {
      token,
      payload: {
        message: {
          token,
          notification: { title, body },
          apns: { payload: { aps: { sound: 'default' } } },
          data: { alert_id: alertId, priority },
        },
      },
    },
  }));
